+using Microsoft.AspNetCore.Mvc;
+using Microsoft.Extensions.ML;
+using TicketClassifier.Models;
+
+namespace TicketClassifier.Controllers;
+
+[ApiController]
+[Route("api/classify")]
+public class TicketClassifierController : ControllerBase
+{
+    private readonly PredictionEnginePool<TicketInput, TicketPrediction> _predictionPool;
+
+    public TicketClassifierController(PredictionEnginePool<TicketInput, TicketPrediction> predictionPool)
+    {
+        _predictionPool = predictionPool;
+    }
+
+    [HttpPost]
+    public ActionResult<ClassifyResponse> Classify([FromBody] ClassifyRequest request)
+    {
+        var input = new TicketInput
+        {
+            Subject = request.Subject,
+            Description = request.Description,
+            Priority = request.Priority
+        };
+
+        var prediction = _predictionPool.Predict(input);
+
+        // Map scores to category labels
+        var labels = new[] { "Billing", "General", "Technical" };
+        var confidenceScores = new Dictionary<string, float>();
+        for (var i = 0; i < prediction.Score.Length && i < labels.Length; i++)
+        {
+            confidenceScores[labels[i]] = prediction.Score[i];
+        }
+
+        return Ok(new ClassifyResponse
+        {
+            PredictedCategory = prediction.PredictedLabel,
+            ConfidenceScores = confidenceScores
+        });
+    }
+
+    [HttpGet("health")]
+    public IActionResult Health()
+    {
+        try
+        {
+            _predictionPool.Predict(new TicketInput
+            {
+                Subject = "test",
+                Description = "test",
+                Priority = 1
+            });
+            return Ok(new { status = "ok" });
+        }
+        catch (Exception ex)
+        {
+            return StatusCode(503, new { status = "error", message = ex.Message });
+        }
+    }
+}
