         var model = pipeline.Fit(dataView);
         _mlContext.Model.Save(model, dataView.Schema, modelPath);
         _logger.LogInformation("Model saved to {Path}", modelPath);

         return new TrainingMetrics(avgMicro, avgMacro, avgLogLoss);
     }
 }

