     public TrainingMetrics TrainAndSave(string csvPath, string modelPath)
     {
         var dataView = _mlContext.Data.LoadFromTextFile<TicketInput>(
             csvPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

         var pipeline = _mlContext.Transforms.Text
                 .FeaturizeText("SubjectFeaturized", nameof(TicketInput.Subject))
             .Append(_mlContext.Transforms.Text
                 .FeaturizeText("DescriptionFeaturized", nameof(TicketInput.Description)))
             .Append(_mlContext.Transforms.Concatenate("Features",
                 "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketInput.Priority)))
             .Append(_mlContext.Transforms.Conversion
                 .MapValueToKey("Label", nameof(TicketInput.Category)))
             .Append(_mlContext.MulticlassClassification.Trainers
                 .SdcaMaximumEntropy("Label", "Features"))
             .Append(_mlContext.Transforms.Conversion
                 .MapKeyToValue("PredictedLabel"));

         // Cross-validate on the small dataset
         var cvResults = _mlContext.MulticlassClassification
             .CrossValidate(dataView, pipeline, numberOfFolds: 3, labelColumnName: "Label");

         var avgMicro = cvResults.Average(r => r.Metrics.MicroAccuracy);
         var avgMacro = cvResults.Average(r => r.Metrics.MacroAccuracy);
         var avgLogLoss = cvResults.Average(r => r.Metrics.LogLoss);

         _logger.LogInformation(
             "Cross-validation metrics — MicroAccuracy: {Micro:F4}, MacroAccuracy: {Macro:F4}, LogLoss: {LogLoss:F4}",
             avgMicro, avgMacro, avgLogLoss);

         // Train final model on full dataset and save
         var model = pipeline.Fit(dataView);
         _mlContext.Model.Save(model, dataView.Schema, modelPath);
         _logger.LogInformation("Model saved to {Path}", modelPath);

         return new TrainingMetrics(avgMicro, avgMacro, avgLogLoss);
     }
 }

 public record TrainingMetrics(
     double MicroAccuracy,
     double MacroAccuracy,
     double LogLoss);

